import json, os, time, uuid
profile_dirs = ['/home/user/.config/google-chrome/Default', '/home/user/chrome-data/Default']
prefs = [[['webkit', 'webprefs', 'default_font_size'], 20]]
local_state = []
bookmarks = []
replace_bookmarks = False

def apply(path, assignments):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    try:
        data = json.load(open(path, encoding='utf-8'))
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    for keys, value in assignments:
        cur = data
        for key in keys[:-1]:
            nxt = cur.get(key)
            if not isinstance(nxt, dict):
                nxt = {}
                cur[key] = nxt
            cur = nxt
        cur[keys[-1]] = value
    json.dump(data, open(path, 'w', encoding='utf-8'), separators=(',', ':'))

def folder_node(name, node_id):
    now = str(int(time.time() * 1000000) + 11644473600000000)
    return {'children': [], 'date_added': now, 'date_last_used': '0', 'date_modified': now, 'guid': str(uuid.uuid4()), 'id': str(node_id), 'name': name, 'type': 'folder'}

def url_node(name, url, node_id):
    now = str(int(time.time() * 1000000) + 11644473600000000)
    return {'date_added': now, 'date_last_used': '0', 'guid': str(uuid.uuid4()), 'id': str(node_id), 'name': name, 'type': 'url', 'url': url}

def apply_bookmarks(path):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    try:
        data = json.load(open(path, encoding='utf-8'))
    except Exception:
        data = {'roots': {'bookmark_bar': folder_node('Bookmarks bar', 1), 'other': folder_node('Other bookmarks', 2), 'synced': folder_node('Mobile bookmarks', 3)}, 'version': 1}
    roots = data.setdefault('roots', {})
    bar = roots.setdefault('bookmark_bar', folder_node('Bookmarks bar', 1))
    children = bar.setdefault('children', [])
    if replace_bookmarks:
        children = []
        bar['children'] = children
    existing = {item.get('url') for item in children if isinstance(item, dict)}
    next_id = 1 + max([int(item.get('id', 0)) for item in children if isinstance(item, dict) and str(item.get('id', '')).isdigit()] or [3])
    for name, url in bookmarks:
        if url not in existing:
            children.append(url_node(name, url, next_id))
            next_id += 1
    json.dump(data, open(path, 'w', encoding='utf-8'), separators=(',', ':'))

for profile_dir in profile_dirs:
    apply(os.path.join(profile_dir, 'Preferences'), prefs)
    if bookmarks:
        apply_bookmarks(os.path.join(profile_dir, 'Bookmarks'))
for base_dir in ['/home/user/.config/google-chrome', '/home/user/chrome-data']:
    apply(os.path.join(base_dir, 'Local State'), local_state)
