for op, payload in ops:
    if op == 'rgb':
        img = img.convert('RGB')
    elif op == 'grayscale':
        img = img.convert('L')
    elif op == 'mirror':
        img = ImageOps.mirror(img.convert('RGB'))
    elif op == 'flip':
        img = ImageOps.flip(img.convert('RGB'))
    elif op == 'rot180':
        img = img.convert('RGB').transpose(Image.Transpose.ROTATE_180)
    elif op == 'rot90cw':
        img = img.convert('RGB').transpose(Image.Transpose.ROTATE_270)
    elif op == 'resize':
        img = img.resize(tuple(payload), resample)
    elif op == 'square_crop':
        w, h = img.size
        side = min(w, h)
        left = (w - side) // 2
        top = (h - side) // 2
        img = img.crop((left, top, left + side, top + side))
    elif op == 'brightness_under':
        threshold = float(payload)
        for factor in (0.80, 0.65, 0.50, 0.38):
            candidate = ImageEnhance.Brightness(img).enhance(factor)
            mean = sum(ImageStat.Stat(candidate.convert('RGB')).mean) / 3.0
            img = candidate
            if mean < threshold - 1.0:
                break
    elif op == 'contrast':
        img = ImageEnhance.Contrast(img.convert('RGB')).enhance(float(payload))
    elif op == 'saturation':
        img = ImageEnhance.Color(img.convert('RGB')).enhance(float(payload))
        hsv = img.convert('HSV')
        h, s, v = hsv.split()
        s = s.point(lambda value: max(value, 150))
        img = Image.merge('HSV', (h, s, v)).convert('RGB')
    elif op == 'sharpen':
        img = img.convert('RGB').filter(ImageFilter.UnsharpMask(radius=2, percent=int(payload), threshold=0))
    elif op == 'ensure_portrait':
        img = img.convert('RGB')
        if img.size[0] >= img.size[1]:
            img = img.transpose(Image.Transpose.ROTATE_270)
    elif op == 'ensure_square':
        side = int(payload) if payload else min(img.size)
        img = img.convert('RGB').resize((side, side), resample)
os.makedirs(os.path.dirname(dest) or '.', exist_ok=True)
if save_format == 'JPEG' and img.mode not in ('RGB', 'L'):
    img = img.convert('RGB')
img.save(dest, save_format, quality=jpeg_quality)
